// Some portions generated by Claude
/** What the Chart view draws: the distribution of one numeric predicate, or how often each predicate is used. */
import { parseGraphNumber } from "./graph-literals.ts";
import type { GraphEdge, GraphNode } from "./graph-types.ts";

export type NumericSeries = { predicate: string; label: string; values: number[] };

/** The numeric values of each predicate that has at least two, the predicate with most values first. */
export function numericSeriesOf(edges: readonly GraphEdge[], nodeById: ReadonlyMap<string, GraphNode>): NumericSeries[] {
  const series = new Map<string, NumericSeries>();
  for (const edge of edges) {
    const target = nodeById.get(edge.target);
    const value = target ? parseGraphNumber(target) : null;
    if (value === null) continue;
    const entry = series.get(edge.predicate);
    if (entry) entry.values.push(value);
    else series.set(edge.predicate, { predicate: edge.predicate, label: edge.label, values: [value] });
  }
  return [...series.values()]
    .filter((entry) => entry.values.length >= 2)
    .sort((left, right) => right.values.length - left.values.length || left.label.localeCompare(right.label));
}

/** Equal-width bins over the values: 4 to 12 of them, by the square root of the number of values. */
export function histogram(values: readonly number[]) {
  if (!values.length) return [];
  let minimum = Infinity;
  let maximum = -Infinity;
  for (const value of values) {
    if (value < minimum) minimum = value;
    if (value > maximum) maximum = value;
  }
  const binCount = Math.min(12, Math.max(4, Math.ceil(Math.sqrt(values.length))));
  const span = maximum - minimum || 1;
  const bins = Array.from({ length: binCount }, (_, index) => ({
    minimum: minimum + (index / binCount) * span,
    maximum: index === binCount - 1 ? Math.max(maximum, minimum + span) : minimum + ((index + 1) / binCount) * span,
    count: 0,
  }));
  for (const value of values) bins[Math.min(binCount - 1, Math.floor(((value - minimum) / span) * binCount))].count += 1;
  return bins;
}

/** How often each predicate is used, most used first (at most 18). */
export function predicateChartOf(edges: readonly GraphEdge[]) {
  const counts = new Map<string, { label: string; count: number }>();
  for (const edge of edges) {
    const current = counts.get(edge.predicate);
    if (current) current.count += 1;
    else counts.set(edge.predicate, { label: edge.label, count: 1 });
  }
  return [...counts.values()]
    .sort((left, right) => right.count - left.count || left.label.localeCompare(right.label))
    .slice(0, 18);
}
